import json from "./schools.json";
import detailJson from "./schools-detail.json";
import type { SchoolsData, SchoolsDetail } from "@/lib/types";

// Generated by scripts/extract_schools.py — never edit the JSON by hand. Server-only
// (schools-detail.json is ~2MB; only the per-school pages read it).
export const SCHOOLS = json as unknown as SchoolsData;
const DETAIL = detailJson as unknown as SchoolsDetail;

export const TEST_LABELS: Record<string, string> = {
  g3Reading: "Grade 3 reading", g3Writing: "Grade 3 writing", g3Math: "Grade 3 math",
  g6Reading: "Grade 6 reading", g6Writing: "Grade 6 writing", g6Math: "Grade 6 math",
  osslt: "Grade 10 literacy test (OSSLT), first try",
};
export const PROFILE_LABELS: Record<string, string> = {
  notEnglish: "First language not English", newToCanada: "New to Canada (non-English-speaking country)",
  specialEd: "Receiving special education", gifted: "Identified as gifted",
  lowIncome: "School-aged children in low-income households", parentsNoDegree: "Parents with no degree, diploma or certificate",
};

export const getSchool = (id: string) => SCHOOLS.schools.find(s => s.id === id);
export const schoolYears = (id: string) => DETAIL.schools[id] ?? {};
